              className="w-full bg-zinc-800 border border-white/10 p-2 text-xs rounded outline-none focus:border-red-600/50"
              value={newVideo.youtubeId || ''}
              onChange={e => setNewVideo({...newVideo, youtubeId: e.target.value})}
            />
