                    onClick={() => onDelete(video.id)}
                    className="p-1.5 hover:bg-red-900/40 rounded text-white/40 hover:text-red-500 transition-colors ml-2"
                  >
                    <Trash2 size={14} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

