    <div className="fixed bottom-0 left-0 w-full z-[1000] bg-zinc-900 border-t-2 border-red-600 p-4 md:p-6 shadow-[0_-20px_50px_rgba(0,0,0,0.8)] animate-in slide-in-from-bottom duration-300">
